def _progress_init(self):
    """
    Init counters used by progress logging
    """
    self.total_steps = 0
    for item in self.item_list:
        # Directories require 4 steps, files only one
        if item.is_directory:
            self.total_steps += 4
        else:
            self.total_steps += 1
    self.current_step = 0
